int liczba = 0;

const byte cyfry[10] = {
  0b0000001,
  0b1001111,
  0b0010010,
  0b0000110,
  0b1001100,
  0b0100100,
  0b0100000,
  0b0001111,
  0b0000000,
  0b0000100
};

void Znak(int numer) {
  byte wzor = cyfry[numer];

  byte portD = ((wzor >> 1) & 0b00111111) << 2;
  byte portB = wzor & 1;

  PORTD = (PORTD & 0b00000011) | portD;

  if (portB)
    PORTB |= 1;
  else
    PORTB &= 0b11111110;
}

void Wyswietl() {
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  Znak(liczba / 10);
  digitalWrite(10, HIGH);
  delay(3);
  digitalWrite(10, LOW);

  Znak(liczba % 10);
  digitalWrite(11, HIGH);
  delay(3);
  digitalWrite(11, LOW);
}

void setup() {
  DDRD |= 0b11111100;
  DDRB |= 0b00001101;

  digitalWrite(10, LOW);
  digitalWrite(11, LOW);
}

void loop() {
  static unsigned long czas = 0;

  Wyswietl();

  if (millis() - czas >= 1000) {
    czas = millis();

    liczba++;

    if (liczba > 99)
      liczba = 0;
  }
}
